<?php
require_once __DIR__ . '/../includes/auth.php'; wajibAdminArea();
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/pembayaran_helper.php';
pastikanTagihanBulanIni($pdo);
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$pesan=''; $jenis='success';
$flash=$_GET['pesan']??'';
$map=['tambah'=>'Pembayaran berhasil dicatat.','ubah'=>'Data pembayaran berhasil diperbarui.','hapus'=>'Data pembayaran berhasil dihapus.'];
if(isset($map[$flash])) $pesan=$map[$flash]; elseif($flash==='tidak_ditemukan'){ $pesan='Data pembayaran tidak ditemukan.';$jenis='warning';}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['aksi']??'')==='hapus'){
 $token=$_POST['csrf_token']??''; $id=filter_input(INPUT_POST,'id_pembayaran',FILTER_VALIDATE_INT);
 if(!hash_equals($_SESSION['csrf_token'],$token)){ $pesan='Permintaan tidak valid.';$jenis='danger'; }
 elseif(!$id){$pesan='Data pembayaran tidak valid.';$jenis='danger';}
 else { $s=$pdo->prepare('DELETE FROM pembayaran WHERE id_pembayaran=:id');$s->execute(['id'=>$id]); header('Location: pembayaran.php?pesan='.($s->rowCount()?'hapus':'tidak_ditemukan'));exit; }
}
$cari=trim($_GET['cari']??'');$status=trim($_GET['status']??'');$params=[];
$sql="SELECT b.id_pembayaran,b.id_penghuni,b.tanggal_pembayaran,b.periode_sewa,b.jumlah_pembayaran,b.status_pembayaran,p.nama,k.nomor_kamar FROM pembayaran b JOIN penghuni p ON p.id_penghuni=b.id_penghuni LEFT JOIN kamar k ON k.id_kamar=p.id_kamar WHERE 1=1";
if($cari!==''){ $sql.=' AND (p.nama LIKE :nama OR k.nomor_kamar LIKE :kamar OR b.periode_sewa LIKE :periode)';$like="%$cari%";$params+=['nama'=>$like,'kamar'=>$like,'periode'=>$like]; }
if(in_array($status,['lunas','belum_bayar'],true)){ $sql.=' AND b.status_pembayaran=:status';$params['status']=$status; }
$sql.=' ORDER BY b.tanggal_pembayaran DESC,b.id_pembayaran DESC';$st=$pdo->prepare($sql);$st->execute($params);$data=$st->fetchAll();
$total=(int)$pdo->query('SELECT COUNT(*) FROM pembayaran')->fetchColumn();$lunas=(float)$pdo->query("SELECT COALESCE(SUM(jumlah_pembayaran),0) FROM pembayaran WHERE status_pembayaran='lunas'")->fetchColumn();$belum=(int)$pdo->query("SELECT COUNT(*) FROM pembayaran WHERE status_pembayaran='belum_bayar'")->fetchColumn();
function eBayar($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function rpBayar($v){return 'Rp '.number_format((float)$v,0,',','.');} function tBayar($v,$status=''){return $status==='belum_bayar' ? '-' : ($v?date('d M Y',strtotime($v)):'-');}
?>
