<?php if($pesan):?><div class="alert alert-<?=eBayar($jenis)?> alert-dismissible fade show"><i class="bi bi-info-circle me-2"></i><?=eBayar($pesan)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif;?>
<section class="row g-3 mb-4"><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Total transaksi</span><span class="stat-icon icon-blue"><i class="bi bi-receipt"></i></span></div><div class="stat-value"><?=number_format($total)?></div><div class="stat-foot">Seluruh pencatatan pembayaran</div></div></div><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Total lunas</span><span class="stat-icon icon-green"><i class="bi bi-wallet2"></i></span></div><div class="stat-value" style="font-size:22px"><?=rpBayar($lunas)?></div><div class="stat-foot">Akumulasi pembayaran lunas</div></div></div><div class="col-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Belum lunas</span><span class="stat-icon icon-orange"><i class="bi bi-clock-history"></i></span></div><div class="stat-value"><?=number_format($belum)?></div><div class="stat-foot">Perlu ditindaklanjuti</div></div></div></section>
<section class="panel"><div class="d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3 mb-4"><div><h2 class="panel-title">Riwayat pembayaran</h2><div class="panel-subtitle">Semua transaksi yang tersimpan di database.</div></div><form method="get" class="d-flex flex-column flex-sm-row gap-2"><input name="cari" class="form-control" placeholder="Cari nama, kamar, periode..." value="<?=eBayar($cari)?>"><select name="status" class="form-select" style="min-width:135px"><option value="">Semua status</option><option value="lunas" <?=$status==='lunas'?'selected':''?>>Lunas</option><option value="belum_bayar" <?=$status==='belum_bayar'?'selected':''?>>Belum lunas</option></select><button class="btn btn-outline-secondary"><i class="bi bi-search"></i> Cari</button><?php if($cari||$status):?><a class="btn btn-outline-secondary" href="pembayaran.php">Reset</a><?php endif;?></form></div>
<div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>No.</th><th>Penghuni</th><th>Kamar</th><th>Periode</th><th>Tanggal</th><th>Jumlah</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="8"><div class="empty-state"><i class="bi bi-wallet2"></i><strong class="d-block text-dark mb-1">Belum ada pembayaran</strong><span>Catat pembayaran pertama untuk mulai membuat riwayat.</span></div></td></tr><?php else: foreach($data as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=eBayar($r['nama'])?></strong></td><td><?=eBayar($r['nomor_kamar']??'-')?></td><td><?=eBayar($r['periode_sewa'])?></td><td><?=tBayar($r['tanggal_pembayaran'],$r['status_pembayaran'])?></td><td class="fw-semibold"><?=rpBayar($r['jumlah_pembayaran'])?></td><td><?php if($r['status_pembayaran']==='lunas'):?><span class="soft-badge"><i class="bi bi-check-circle"></i>Lunas</span><?php else:?><span class="soft-badge pending"><i class="bi bi-clock"></i>Belum lunas</span><?php endif;?></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-primary" href="pembayaran_edit.php?id=<?=(int)$r['id_pembayaran']?>"><i class="bi bi-pencil-square"></i></a> <form method="post" class="d-inline" onsubmit="return confirm('Hapus transaksi ini?');"><input type="hidden" name="csrf_token" value="<?=eBayar($_SESSION['csrf_token'])?>"><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id_pembayaran" value="<?=(int)$r['id_pembayaran']?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash3"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>